import type * as React from 'react';
export type ToastSeverity = 'normal' | 'success' | 'info' | 'warn' | 'error' | 'secondary' | 'contrast';
export type ToastId = string | number;
export type ToastType = {
    id?: ToastId;
    title?: React.ReactNode | string;
    description?: React.ReactNode | string;
    action?: React.ButtonHTMLAttributes<HTMLButtonElement>;
    dismissible?: boolean;
    severity?: ToastSeverity;
    loading?: boolean;
    icon?: React.ReactNode;
    render?: React.ReactElement;
    duration?: number;
    group?: string;
    promise?: unknown;
    /**
     * Arbitrary user-defined key/value metadata attached to the toast.
     * Available on the toast object inside callbacks (onDismiss, onTimeout)
     * and via the manager's snapshot.
     */
    data?: Record<string, unknown>;
    onDismiss?: (toast: ToastType) => void;
    onTimeout?: (toast: ToastType) => void;
};
export type ToastPromiseType<T = unknown> = {
    loading: ToastType;
    success?: ToastType | ((data: T) => ToastType | void);
    error?: ToastType | ((error: unknown) => ToastType | void);
};
export type ToastEvent = {
    action: 'add';
    toast: ToastType;
} | {
    action: 'update';
    toast: ToastType;
} | {
    action: 'remove';
    id: ToastId;
} | {
    action: 'dismiss';
    id?: ToastId;
} | {
    action: 'clear';
    group?: string;
};
export type ToastEventListener = (event: ToastEvent) => void;
export interface ToastManager {
    snapshot(): ToastType[];
    subscribe(listener: ToastEventListener): () => void;
    add(toast: ToastType): ToastId;
    update(id: ToastId, updates: Partial<ToastType>): ToastId;
    dismiss(id?: ToastId): void;
    remove(id: ToastId): void;
    promise<T>(promise: Promise<T>, options: ToastPromiseType<T>): Promise<T>;
    success(toast: ToastType): ToastId;
    info(toast: ToastType): ToastId;
    warn(toast: ToastType): ToastId;
    error(toast: ToastType): ToastId;
    secondary(toast: ToastType): ToastId;
    contrast(toast: ToastType): ToastId;
}
export type ToastFunction = ((toast: ToastType) => ToastId) & {
    update(id: ToastId, updates: Partial<ToastType>): ToastId;
    dismiss(id?: ToastId): void;
    promise<T>(promise: Promise<T>, options: ToastPromiseType<T>): Promise<T>;
    success(toast: ToastType): ToastId;
    info(toast: ToastType): ToastId;
    warn(toast: ToastType): ToastId;
    error(toast: ToastType): ToastId;
    secondary(toast: ToastType): ToastId;
    contrast(toast: ToastType): ToastId;
};
